        final Function<String, String> normalizeToString = toString -> {
            final int open = toString.indexOf('[');
            final int close = toString.lastIndexOf(']');
            final String prefix = toString.substring(0, open);
            final List<String> fields = new ArrayList<>(Arrays.asList(toString.substring(open + 1, close).split(",")));
            Collections.sort(fields);
            return prefix + "[" + String.join(",", fields) + "]";
