    @Test
    public void testReflectionStatics() {
        final ReflectionStaticFieldsFixture instance1 = new ReflectionStaticFieldsFixture();
        final java.util.function.Function<String, String> normalizeToString = s -> {
            final int start = s.indexOf('[');
            final int end = s.lastIndexOf(']');
            final String fields = s.substring(start + 1, end);
            final List<String> fieldList = new ArrayList<>(java.util.Arrays.asList(fields.split(",")));
            java.util.Collections.sort(fieldList);
            return s.substring(0, start) + "[" + String.join(",", fieldList) + "]";
        };
        assertEquals(
            normalizeToString.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]"),
            normalizeToString.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeToString.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,staticTransientString=staticTransientString,staticTransientInt=54321,instanceString=instanceString,instanceInt=67890,transientString=transientString,transientInt=98765]"),
