    @Test
    public void stringArray() {
        final WithArrays wa = new WithArrays();
        wa.stringArray = new String[] { "a", "A" };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray=<null>," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray={" + BR
                   + "    a," + BR
                   + "    A" + BR
                   + "  }" + BR
                   + "]";
        final String actual = toString(wa);

        final java.util.function.Function<String, java.util.Map<String, String>> toFieldMap = s -> {
            final String[] lines = s.split("\\R");
            final java.util.Map<String, String> fields = new java.util.LinkedHashMap<>();
            StringBuilder current = null;
            String currentKey = null;
            for (int i = 1; i < lines.length - 1; i++) {
                final String line = lines[i];
                if (line.startsWith("  ") && !line.startsWith("    ") && line.contains("=")) {
                    if (currentKey != null) {
                        fields.put(currentKey, current.toString());
                    }
                    current = new StringBuilder(line);
                    currentKey = line.substring(2, line.indexOf('='));
                } else if (current != null) {
                    current.append(BR).append(line);
                }
            }
            if (currentKey != null) {
                fields.put(currentKey, current.toString());
            }
            return fields;
        };

        final String[] expectedLines = exp.split("\\R");
        final String[] actualLines = actual.split("\\R");
        assertEquals(expectedLines[0], actualLines[0]);
        assertEquals(expectedLines[expectedLines.length - 1], actualLines[actualLines.length - 1]);
        assertEquals(toFieldMap.apply(exp), toFieldMap.apply(actual));
    }
