  @Test
  public void testAvroDoc() {
    Schema schema = ReflectData.get().getSchema(DocTest.class);

    assertNotNull(schema);
    assertEquals("DocTest", schema.getName());
    assertEquals("org.apache.avro.reflect.TestReflect", schema.getNamespace());
    assertEquals("DocTest class docs", schema.getDoc());
    assertEquals(Schema.Type.RECORD, schema.getType());

    Map<String, Field> fields = new HashMap<>();
    for (Field field : schema.getFields()) {
      fields.put(field.name(), field);
    }

    assertEquals(new HashSet<>(Arrays.asList("foo", "enums", "defaultTest")), fields.keySet());

    Field foo = fields.get("foo");
    assertNotNull(foo);
    assertEquals("Some Documentation", foo.doc());
    assertEquals(Schema.Type.INT, foo.schema().getType());

    Field enums = fields.get("enums");
    assertNotNull(enums);
    assertEquals("Some other Documentation", enums.doc());
    Schema enumSchema = enums.schema();
    assertEquals(Schema.Type.ENUM, enumSchema.getType());
    assertEquals("DocTestEnum", enumSchema.getName());
    assertEquals(Arrays.asList("ENUM_1", "ENUM_2"), enumSchema.getEnumSymbols());

    Field defaultTest = fields.get("defaultTest");
    assertNotNull(defaultTest);
    assertEquals("And again", defaultTest.doc());
    Schema defaultTestSchema = defaultTest.schema();
    assertEquals(Schema.Type.RECORD, defaultTestSchema.getType());
    assertEquals("DefaultTest", defaultTestSchema.getName());

    Field defaultTestFoo = defaultTestSchema.getField("foo");
    assertNotNull(defaultTestFoo);
    assertEquals(Schema.Type.INT, defaultTestFoo.schema().getType());
    assertEquals(1, defaultTestFoo.defaultValue().asInt());
  }
