    NodeList names = root.getElementsByTagName("name");
    assertThat(names.getLength()).isEqualTo(1);
    assertThat(names.item(0).getTextContent()).isEqualTo("Jenny");

    NodeList phoneNumbers = root.getElementsByTagName("phone_number");
    assertThat(phoneNumbers.getLength()).isEqualTo(1);
    Element phoneNumber = (Element) phoneNumbers.item(0);
    assertThat(phoneNumber.getAttribute("type")).isEqualTo("MOBILE");

    NodeList numbers = phoneNumber.getElementsByTagName("number");
    assertThat(numbers.getLength()).isEqualTo(1);
    assertThat(numbers.item(0).getTextContent()).isEqualTo("867-5309");
  }
