    @Test
    public void testPerson() {
        final Person p = new Person();
        p.name = "John Doe";
        p.age = 33;
        p.smoker = false;
        p.job = new Job();
        p.job.title = "Manager";
        final String pBaseStr = p.getClass().getName() + "@" + Integer.toHexString(System.identityHashCode(p));
        final String pJobStr = p.job.getClass().getName() + "@" + Integer.toHexString(System.identityHashCode(p.job));

        final String actual = new ReflectionToStringBuilder(p, new RecursiveToStringStyle()).toString();

        assertEquals(pBaseStr, actual.substring(0, actual.indexOf('[')));

        final String actualBody = actual.substring(actual.indexOf('[') + 1, actual.lastIndexOf(']'));
        final HashMap<String, String> actualFields = new HashMap<>();
        for (final String entry : actualBody.split(",")) {
            final int idx = entry.indexOf('=');
            actualFields.put(entry.substring(0, idx), entry.substring(idx + 1));
        }

        final HashMap<String, String> expectedFields = new HashMap<>();
        expectedFields.put("name", "John Doe");
        expectedFields.put("age", "33");
        expectedFields.put("smoker", "false");
        expectedFields.put("job", pJobStr + "[title=Manager]");

        assertEquals(expectedFields, actualFields);
    }
