    @Test
    public void testReflectionHashCodeExcludeFields() {
        final TestObjectWithMultipleFields x = new TestObjectWithMultipleFields(1, 1, 1);
        final TestObjectWithMultipleFields xExcludeTwo = new TestObjectWithMultipleFields(1, 2, 1);
        final TestObjectWithMultipleFields xExcludeThree = new TestObjectWithMultipleFields(1, 1, 2);

        assertEquals(((17 * 37 + 1) * 37 + 1) * 37 + 1, HashCodeBuilder.reflectionHashCode(x));

        assertEquals(((17 * 37 + 1) * 37 + 1) * 37 + 1, HashCodeBuilder.reflectionHashCode(x, (String[]) null));
        assertEquals(((17 * 37 + 1) * 37 + 1) * 37 + 1, HashCodeBuilder.reflectionHashCode(x));
        assertEquals(((17 * 37 + 1) * 37 + 1) * 37 + 1, HashCodeBuilder.reflectionHashCode(x, "xxx"));

        assertEquals((17 * 37 + 1) * 37 + 1, HashCodeBuilder.reflectionHashCode(xExcludeTwo, "two"));
        assertEquals((17 * 37 + 1) * 37 + 1, HashCodeBuilder.reflectionHashCode(xExcludeThree, "three"));

        assertEquals(17 * 37 + 1, HashCodeBuilder.reflectionHashCode(x, "two", "three"));

        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three"));
        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three", "xxx"));
    }
