    @Test
    public void testReflectionStatics() {
        final ReflectionStaticFieldsFixture instance1 = new ReflectionStaticFieldsFixture();
        final String base = this.toBaseString(instance1);

        final BiConsumer<String, Map<String, String>> assertContent = (actual, expected) -> {
            assertTrue(actual.startsWith(base + "["), actual);
            assertTrue(actual.endsWith("]"), actual);
            final String content = actual.substring(base.length() + 1, actual.length() - 1);
            final Map<String, String> actualFields = new HashMap<>();
            for (final String field : content.split(",")) {
                final String[] entry = field.split("=", 2);
                actualFields.put(entry[0], entry[1]);
            }
            assertEquals(expected, actualFields, actual);
        };

        final Map<String, String> expectedWithoutTransients = new HashMap<>();
        expectedWithoutTransients.put("staticString", "staticString");
        expectedWithoutTransients.put("staticInt", "12345");
        expectedWithoutTransients.put("instanceString", "instanceString");
        expectedWithoutTransients.put("instanceInt", "67890");

        assertContent.accept(
            ReflectionToStringBuilder.toString(instance1, null, false, true, ReflectionStaticFieldsFixture.class),
            expectedWithoutTransients);

        final Map<String, String> expectedWithTransients = new HashMap<>();
        expectedWithTransients.put("staticString", "staticString");
        expectedWithTransients.put("staticInt", "12345");
        expectedWithTransients.put("staticTransientString", "staticTransientString");
        expectedWithTransients.put("staticTransientInt", "54321");
        expectedWithTransients.put("instanceString", "instanceString");
        expectedWithTransients.put("instanceInt", "67890");
        expectedWithTransients.put("transientString", "transientString");
        expectedWithTransients.put("transientInt", "98765");

        assertContent.accept(
            ReflectionToStringBuilder.toString(instance1, null, true, true, ReflectionStaticFieldsFixture.class),
            expectedWithTransients);

        assertContent.accept(
            this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class),
            expectedWithoutTransients);
        assertContent.accept(
            this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class),
            expectedWithoutTransients);
    }
