    @Test
    public void testReflectionHierarchyArrayList() {
        // LANG-1337 without this, the generated string can differ depending on the JVM version/vendor
        final List<Object> list = new ArrayList<>(ARRAYLIST_INITIAL_CAPACITY);
        final String baseString = this.toBaseString(list);

        final java.util.function.Function<String, Map<String, String>> toFieldMap = s -> {
            final Map<String, String> fields = new HashMap<>();
            final int open = s.indexOf('[');
            final int close = s.lastIndexOf(']');
            final String content = s.substring(open + 1, close);
            if (content.isEmpty()) {
                return fields;
            }
            for (final String field : content.split(",(?=[a-zA-Z_$][\\w$]*=)")) {
                final int eq = field.indexOf('=');
                fields.put(field.substring(0, eq), field.substring(eq + 1));
            }
            return fields;
        };

        final String expectedWithTransients = baseString
                + "[elementData={<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>},size=0,modCount=0]";
        final String toStringWithTransients = ToStringBuilder.reflectionToString(list, null, true);
        assertEquals(expectedWithTransients.substring(0, expectedWithTransients.indexOf('[')),
                toStringWithTransients.substring(0, toStringWithTransients.indexOf('[')));
        assertEquals(toFieldMap.apply(expectedWithTransients), toFieldMap.apply(toStringWithTransients));

        final String expectedWithoutTransients = baseString + "[size=0]";
        final String toStringWithoutTransients = ToStringBuilder.reflectionToString(list, null, false);
        assertEquals(expectedWithoutTransients.substring(0, expectedWithoutTransients.indexOf('[')),
                toStringWithoutTransients.substring(0, toStringWithoutTransients.indexOf('[')));
        assertEquals(toFieldMap.apply(expectedWithoutTransients), toFieldMap.apply(toStringWithoutTransients));
    }
