    @Test
    public void testReflectionHierarchy() {
        final java.util.function.UnaryOperator<String> canonical = s -> {
            final int start = s.indexOf('[');
            final int end = s.lastIndexOf(']');
            final String prefix = s.substring(0, start);
            final String body = s.substring(start + 1, end);
            final List<String> fields = body.isEmpty()
                ? new ArrayList<>()
                : new ArrayList<>(java.util.Arrays.asList(body.split(",", -1)));
            java.util.Collections.sort(fields);
            return prefix + fields;
        };

        final ReflectionTestFixtureA baseA = new ReflectionTestFixtureA();
        String baseString = this.toBaseString(baseA);
        assertEquals(canonical.apply(baseString + "[a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseA)));
        assertEquals(canonical.apply(baseString + "[a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseA, null)));
        assertEquals(canonical.apply(baseString + "[a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseA, null, false)));
        assertEquals(canonical.apply(baseString + "[a=a,transientA=t]"), canonical.apply(ToStringBuilder.reflectionToString(baseA, null, true)));
        assertEquals(canonical.apply(baseString + "[a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseA, null, false, null)));
        assertEquals(canonical.apply(baseString + "[a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseA, null, false, Object.class)));
        assertEquals(canonical.apply(baseString + "[a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseA, null, false, ReflectionTestFixtureA.class)));

        final ReflectionTestFixtureB baseB = new ReflectionTestFixtureB();
        baseString = this.toBaseString(baseB);
        assertEquals(canonical.apply(baseString + "[b=b,a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseB)));
        assertEquals(canonical.apply(baseString + "[b=b,a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseB)));
        assertEquals(canonical.apply(baseString + "[b=b,a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseB, null)));
        assertEquals(canonical.apply(baseString + "[b=b,a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseB, null, false)));
        assertEquals(canonical.apply(baseString + "[b=b,transientB=t,a=a,transientA=t]"), canonical.apply(ToStringBuilder.reflectionToString(baseB, null, true)));
        assertEquals(canonical.apply(baseString + "[b=b,a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseB, null, false, null)));
        assertEquals(canonical.apply(baseString + "[b=b,a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseB, null, false, Object.class)));
        assertEquals(canonical.apply(baseString + "[b=b,a=a]"), canonical.apply(ToStringBuilder.reflectionToString(baseB, null, false, ReflectionTestFixtureA.class)));
        assertEquals(canonical.apply(baseString + "[b=b]"), canonical.apply(ToStringBuilder.reflectionToString(baseB, null, false, ReflectionTestFixtureB.class)));
    }
