    @Test
    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();

        java.util.function.Function<String, String> normalize = value -> {
            final int open = value.indexOf('[');
            final int close = value.lastIndexOf(']');
            final String prefix = value.substring(0, open);
            final String body = value.substring(open + 1, close);

            if (body.isEmpty()) {
                return value;
            }

            final Map<String, String> fields = new java.util.TreeMap<>();
            for (final String field : body.split(",")) {
                final String trimmedField = field.trim();
                final int eq = trimmedField.indexOf('=');
                fields.put(trimmedField.substring(0, eq), trimmedField.substring(eq + 1));
            }

            final StringBuilder normalized = new StringBuilder(prefix).append('[');
            boolean first = true;
            for (final Map.Entry<String, String> entry : fields.entrySet()) {
                if (!first) {
                    normalized.append(',');
                }
                normalized.append(entry.getKey()).append('=').append(entry.getValue());
                first = false;
            }
            normalized.append(']');
            return normalized.toString();
        };

        assertEquals(
            this.toBaseString(instance1) + "[staticInt2=67890,staticString2=staticString2]",
            normalize.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class)));
        assertEquals(
            this.toBaseString(instance1) + "[staticInt=12345,staticInt2=67890,staticString=staticString,staticString2=staticString2]",
            normalize.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            this.toBaseString(instance1) + "[staticInt=12345,staticInt2=67890,staticString=staticString,staticString2=staticString2]",
            normalize.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            this.toBaseString(instance1) + "[staticInt=12345,staticInt2=67890,staticString=staticString,staticString2=staticString2]",
            normalize.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    }
