            assertEquals(
                parseFields.apply(expected.substring(expectedOpen + 1, expectedClose)),
                parseFields.apply(actual.substring(actualOpen + 1, actualClose)));
            assertEquals(expected.substring(expectedClose + 1), actual.substring(actualClose + 1));
        };

        assertReflectionStringEquals.accept(
            this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890]",
