    public void assertGetPoolContent() {
        ThreadPoolParameterInfo threadPoolParameterInfo = ThreadPoolParameterInfo.builder()
                .tenantId("prescription")
                .itemId("dynamic-threadpool-example")
                .tpId("message-consume")
                .content("描述信息")
                .corePoolSize(1)
                .maximumPoolSize(2)
                .queueType(1)
                .capacity(4)
                .keepAliveTime(513)
                .executeTimeOut(null)
                .rejectedType(4)
                .isAlarm(1)
                .capacityAlarm(80)
                .livenessAlarm(80)
                .allowCoreThreadTimeOut(1)
                .build();

        String poolContent = ContentUtil.getPoolContent(threadPoolParameterInfo);

        Map<String, String> expected = new HashMap<>();
        expected.put("tenantId", "\"prescription\"");
        expected.put("itemId", "\"dynamic-threadpool-example\"");
        expected.put("tpId", "\"message-consume\"");
        expected.put("queueType", "1");
        expected.put("capacity", "4");
        expected.put("keepAliveTime", "513");
        expected.put("rejectedType", "4");
        expected.put("isAlarm", "1");
        expected.put("capacityAlarm", "80");
        expected.put("livenessAlarm", "80");
        expected.put("allowCoreThreadTimeOut", "1");

        String trimmed = poolContent.trim();
        Assert.isTrue(trimmed.startsWith("{") && trimmed.endsWith("}"),
                "Pool content should be a JSON object: " + poolContent);

        String body = trimmed.substring(1, trimmed.length() - 1);
        String[] entries = body.split(",");
        Map<String, String> actual = new HashMap<>();

        for (String entry : entries) {
            String normalizedEntry = entry.trim();
            int colonIdx = normalizedEntry.indexOf(':');
            Assert.isTrue(colonIdx > 0, "Invalid JSON entry: " + entry);

            String key = normalizedEntry.substring(0, colonIdx).trim().replace("\"", "");
            String value = normalizedEntry.substring(colonIdx + 1).trim();
            actual.put(key, value);
        }

        Assert.isTrue(expected.equals(actual), "Unexpected pool content: " + poolContent);
    }
