//<fix start>
  @Test public void xmlRequestBody() throws Exception {
    server.enqueue(new MockResponse());

    Call<Void> call = service.postXml(SAMPLE_CONTACT);
    call.execute();

    RecordedRequest request = server.takeRequest();
    assertThat(request.getHeader("Content-Type")).isEqualTo("application/xml; charset=utf-8");

    DocumentBuilderFactory documentBuilderFactory = DocumentBuilderFactory.newInstance();
    documentBuilderFactory.setNamespaceAware(false);
    documentBuilderFactory.setIgnoringElementContentWhitespace(true);
    DocumentBuilder documentBuilder = documentBuilderFactory.newDocumentBuilder();

    Document expectedDocument = documentBuilder.parse(new InputSource(new StringReader(SAMPLE_CONTACT_XML)));
    Document actualDocument = documentBuilder.parse(new InputSource(new StringReader(request.getBody().readUtf8())));

    class XmlCanonicalizer {
      String canonicalize(Node node) {
        if (node.getNodeType() == Node.TEXT_NODE || node.getNodeType() == Node.CDATA_SECTION_NODE) {
          return node.getNodeValue().trim();
        }
        if (node.getNodeType() != Node.ELEMENT_NODE) {
          return "";
        }

        Element element = (Element) node;
        StringBuilder sb = new StringBuilder();
        sb.append("<").append(element.getTagName());

        List<String> attrs = new ArrayList<>();
        NamedNodeMap attributes = element.getAttributes();
        for (int i = 0; i < attributes.getLength(); i++) {
          Node attr = attributes.item(i);
          attrs.add(attr.getNodeName() + "=\"" + attr.getNodeValue() + "\"");
        }
        Collections.sort(attrs);
        for (String attr : attrs) {
          sb.append(" ").append(attr);
        }
        sb.append(">");

        StringBuilder text = new StringBuilder();
        List<String> children = new ArrayList<>();
        NodeList childNodes = element.getChildNodes();
        for (int i = 0; i < childNodes.getLength(); i++) {
          Node child = childNodes.item(i);
          if (child.getNodeType() == Node.ELEMENT_NODE) {
            children.add(canonicalize(child));
          } else if (child.getNodeType() == Node.TEXT_NODE || child.getNodeType() == Node.CDATA_SECTION_NODE) {
            text.append(child.getNodeValue());
          }
        }

        String textContent = text.toString().trim();
        if (!textContent.isEmpty()) {
          sb.append(textContent);
        }

        Collections.sort(children);
        for (String child : children) {
          sb.append(child);
        }

        sb.append("</").append(element.getTagName()).append(">");
        return sb.toString();
      }
    }

    XmlCanonicalizer canonicalizer = new XmlCanonicalizer();
    assertThat(canonicalizer.canonicalize(actualDocument.getDocumentElement()))
        .isEqualTo(canonicalizer.canonicalize(expectedDocument.getDocumentElement()));
  }
