    @Test
    public void testSimpleReflectionStatics() {
        final SimpleReflectionStaticFieldsFixture instance1 = new SimpleReflectionStaticFieldsFixture();
        final String expected = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345]";
        final Function<String, String> normalizeToString = s -> {
            final int open = s.indexOf('[');
            final int close = s.lastIndexOf(']');
            if (open == -1 || close == -1 || open > close) {
                return s;
            }
            final String prefix = s.substring(0, open);
            final String suffix = s.substring(close + 1);
            final String content = s.substring(open + 1, close);
            final List<String> fields = new ArrayList<>(Arrays.asList(content.split(",", -1)));
            Collections.sort(fields);
            return prefix + "[" + String.join(",", fields) + "]" + suffix;
        };
        final String normalizedExpected = normalizeToString.apply(expected);

        assertEquals(normalizedExpected,
            normalizeToString.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(normalizedExpected,
            normalizeToString.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(normalizedExpected,
            normalizeToString.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(normalizedExpected,
            normalizeToString.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    }
