    @Test
    public void testSelfInstanceTwoVarsReflectionObjectCycle() {
        final SelfInstanceTwoVarsReflectionTestFixture test = new SelfInstanceTwoVarsReflectionTestFixture();
        final String actual = test.toString();
        final String prefix = this.toBaseString(test);

        final int openBracket = actual.indexOf('[');
        final int closeBracket = actual.lastIndexOf(']');
        assertTrue(openBracket > 0, "actual string should contain an opening bracket");
        assertTrue(closeBracket > openBracket, "actual string should contain a closing bracket");

        assertEquals(prefix + "[", actual.substring(0, openBracket + 1));
        assertEquals("]", actual.substring(closeBracket));

        final String body = actual.substring(openBracket + 1, closeBracket);
        final String[] fieldEntries = body.split(",", -1);
        assertEquals(2, fieldEntries.length, "Expected exactly two fields, with no trailing field separator");

        final Map<String, String> actualFields = new HashMap<>();
        for (final String fieldEntry : fieldEntries) {
            final int equalsIndex = fieldEntry.indexOf('=');
            assertTrue(equalsIndex > 0, "Unexpected field format: " + fieldEntry);
            actualFields.put(fieldEntry.substring(0, equalsIndex), fieldEntry.substring(equalsIndex + 1));
        }

        final Map<String, String> expectedFields = new HashMap<>();
        expectedFields.put("typeIsSelf", prefix);
        expectedFields.put("otherType", test.getOtherType().toString());

        assertEquals(expectedFields, actualFields);
    }
