        assertEquals("parent.callback", jsonpObject.getFunction());

        assertEquals(3, jsonpObject.getParameters().size());
        JSONObject param = (JSONObject) jsonpObject.getParameters().get(0);
        assertEquals(1, param.get("id"));
        assertEquals("ido)nans", param.get("name"));

        String json = JSON.toJSONString(jsonpObject, SerializerFeature.BrowserSecure);

        String prefix = "/**/parent.callback(";
        assertTrue(json.startsWith(prefix));
        assertTrue(json.endsWith(")"));

        String inner = json.substring(prefix.length(), json.length() - 1);
        JSONArray actualParams = JSON.parseArray("[" + inner + "]");

        assertEquals(3, actualParams.size());
        assertEquals(param, actualParams.get(0));
        assertEquals(Integer.valueOf(1), actualParams.get(1));
        assertEquals(Integer.valueOf(2), actualParams.get(2));

        assertTrue(json.contains("ido\\u0029nans"));
        assertFalse(json.contains("ido)nans"));
    }
