    @Test
    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();

        java.util.function.Function<String, Map<String, String>> parseFields = s -> {
            Map<String, String> fields = new HashMap<>();
            for (String field : s.split(",")) {
                if (field.isEmpty()) {
                    continue;
                }
                int eq = field.indexOf('=');
                fields.put(field.substring(0, eq), field.substring(eq + 1));
            }
            return fields;
        };

        java.util.function.BiConsumer<String, String> assertReflectionStringEquals = (expected, actual) -> {
            int expectedBracket = expected.indexOf('[');
            int actualBracket = actual.indexOf('[');

            List<Object> expectedParts = new ArrayList<>();
            expectedParts.add(expected.substring(0, expectedBracket));
            expectedParts.add(parseFields.apply(expected.substring(expectedBracket + 1, expected.lastIndexOf(']'))));

            List<Object> actualParts = new ArrayList<>();
            actualParts.add(actual.substring(0, actualBracket));
            actualParts.add(parseFields.apply(actual.substring(actualBracket + 1, actual.lastIndexOf(']'))));

            assertEquals(expectedParts, actualParts);
        };

        assertReflectionStringEquals.accept(
            this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890]",
            ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class));
        assertReflectionStringEquals.accept(
            this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]",
            ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class));
        assertReflectionStringEquals.accept(
            this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]",
            this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class));
        assertReflectionStringEquals.accept(
            this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]",
            this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class));
    }
