//<fix start>
    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        String expectedWhereAllIfColumns = "<where><if test=\"id != null\"> AND id = #{id}</if><if test=\"username != null\"> AND username = #{username}</if> AND is_valid = 1</where>";

        Assert.assertTrue("where prefix missing", whereAllIfColumns.startsWith("<where>"));
        Assert.assertTrue("where suffix missing", whereAllIfColumns.endsWith("</where>"));

        java.util.regex.Pattern ifPattern = java.util.regex.Pattern.compile("<if\\b[^>]*>.*?</if>");

        // Normalize expected <where> value.
        String expectedInner = expectedWhereAllIfColumns.substring("<where>".length(), expectedWhereAllIfColumns.length() - "</where>".length());
        java.util.regex.Matcher expectedMatcher = ifPattern.matcher(expectedInner);
        java.util.List<String> expectedIfs = new java.util.ArrayList<String>();
        int expectedLastEnd = 0;
        while (expectedMatcher.find()) {
            expectedIfs.add(expectedMatcher.group());
            expectedLastEnd = expectedMatcher.end();
        }
        String expectedTrailing = expectedInner.substring(expectedLastEnd);
        java.util.Collections.sort(expectedIfs);
        StringBuilder normalizedExpected = new StringBuilder("<where>");
        for (String block : expectedIfs) {
            normalizedExpected.append(block);
        }
        normalizedExpected.append(expectedTrailing).append("</where>");

        // Normalize actual <where> value.
        String actualInner = whereAllIfColumns.substring("<where>".length(), whereAllIfColumns.length() - "</where>".length());
        java.util.regex.Matcher actualMatcher = ifPattern.matcher(actualInner);
        java.util.List<String> actualIfs = new java.util.ArrayList<String>();
        int actualLastEnd = 0;
        while (actualMatcher.find()) {
            actualIfs.add(actualMatcher.group());
            actualLastEnd = actualMatcher.end();
        }
        String actualTrailing = actualInner.substring(actualLastEnd);

        // Make sure the actual content is exactly a sequence of <if> blocks followed by trailing logic-delete condition.
        StringBuilder actualConcatenated = new StringBuilder();
        for (String block : actualIfs) {
            actualConcatenated.append(block);
        }
        actualConcatenated.append(actualTrailing);
        Assert.assertEquals("Unexpected non-if content in whereAllIfColumns", actualInner, actualConcatenated.toString());

        java.util.Collections.sort(actualIfs);
        StringBuilder normalizedActual = new StringBuilder("<where>");
        for (String block : actualIfs) {
            normalizedActual.append(block);
        }
        normalizedActual.append(actualTrailing).append("</where>");

        Assert.assertEquals(normalizedExpected.toString(), normalizedActual.toString());

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        Assert.assertEquals("<set>username = #{username},is_valid = 1,</set>", updateSetColumns);
    }
