//<fix start>
    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        String expectedWhereAllIfColumns = "<where><if test=\"id != null\"> AND id = #{id}</if><if test=\"username != null\"> AND username = #{username}</if> AND is_valid = 1</where>";

        Assert.assertTrue("where prefix missing", whereAllIfColumns.startsWith("<where>"));
        Assert.assertTrue("where suffix missing", whereAllIfColumns.endsWith("</where>"));
        Assert.assertTrue(expectedWhereAllIfColumns.startsWith("<where>"));
        Assert.assertTrue(expectedWhereAllIfColumns.endsWith("</where>"));

        String expectedWhereInner = expectedWhereAllIfColumns.substring("<where>".length(), expectedWhereAllIfColumns.length() - "</where>".length());
        String actualWhereInner = whereAllIfColumns.substring("<where>".length(), whereAllIfColumns.length() - "</where>".length());

        java.util.regex.Pattern ifPattern = java.util.regex.Pattern.compile("<if\\b[^>]*>.*?</if>");

        java.util.regex.Matcher expectedIfMatcher = ifPattern.matcher(expectedWhereInner);
        java.util.List<String> expectedIfs = new java.util.ArrayList<String>();
        int expectedLastEnd = 0;
        while (expectedIfMatcher.find()) {
            expectedIfs.add(expectedIfMatcher.group());
            expectedLastEnd = expectedIfMatcher.end();
        }
        String expectedWhereTrailing = expectedWhereInner.substring(expectedLastEnd);

        java.util.regex.Matcher actualIfMatcher = ifPattern.matcher(actualWhereInner);
        java.util.List<String> actualIfs = new java.util.ArrayList<String>();
        int actualLastEnd = 0;
        while (actualIfMatcher.find()) {
            actualIfs.add(actualIfMatcher.group());
            actualLastEnd = actualIfMatcher.end();
        }
        String actualWhereTrailing = actualWhereInner.substring(actualLastEnd);

        StringBuilder actualWhereConcatenated = new StringBuilder();
        for (String block : actualIfs) {
            actualWhereConcatenated.append(block);
        }
        actualWhereConcatenated.append(actualWhereTrailing);
        Assert.assertEquals("Unexpected non-if content in whereAllIfColumns", actualWhereInner, actualWhereConcatenated.toString());

        java.util.Collections.sort(expectedIfs);
        java.util.Collections.sort(actualIfs);
        Assert.assertEquals("Order-insensitive <if> blocks mismatch", expectedIfs, actualIfs);
        Assert.assertEquals("Trailing logic-delete condition mismatch", expectedWhereTrailing, actualWhereTrailing);

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        String expectedUpdateSetColumns = "<set>username = #{username},is_valid = 1,</set>";

        Assert.assertTrue("set prefix missing", updateSetColumns.startsWith("<set>"));
        Assert.assertTrue("set suffix missing", updateSetColumns.endsWith("</set>"));
        Assert.assertTrue(expectedUpdateSetColumns.startsWith("<set>"));
        Assert.assertTrue(expectedUpdateSetColumns.endsWith("</set>"));

        String expectedSetInner = expectedUpdateSetColumns.substring("<set>".length(), expectedUpdateSetColumns.length() - "</set>".length());
        String actualSetInner = updateSetColumns.substring("<set>".length(), updateSetColumns.length() - "</set>".length());

        java.util.List<String> expectedSetItems = new java.util.ArrayList<String>(java.util.Arrays.asList(expectedSetInner.split(",", -1)));
        java.util.List<String> actualSetItems = new java.util.ArrayList<String>(java.util.Arrays.asList(actualSetInner.split(",", -1)));

        java.util.Collections.sort(expectedSetItems);
        java.util.Collections.sort(actualSetItems);
        Assert.assertEquals("Order-insensitive <set> items mismatch", expectedSetItems, actualSetItems);
    }
