                HashCodeBuilder.reflectionHashCode(new TestSubObject(value, value, value)));
        assertEquals((((17 * 37 + value) * 37 + value) * 37 + value),
                HashCodeBuilder.reflectionHashCode(new TestSubObject(value, value, value), true));
