//<fix start>
    @Test
    public void testSimpleReflectionStatics() {
        final SimpleReflectionStaticFieldsFixture instance1 = new SimpleReflectionStaticFieldsFixture();
        final String expected = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345]";
        final Function<String, String> normalizeToString = toString -> {
            final int open = toString.indexOf('[');
            final int close = toString.lastIndexOf(']');
            final String prefix = toString.substring(0, open);
            final List<String> fields = new ArrayList<>(Arrays.asList(toString.substring(open + 1, close).split(",", -1)));
            Collections.sort(fields);
            return prefix + "[" + String.join(",", fields) + "]";
        };
        final String normalizedExpected = normalizeToString.apply(expected);

        assertEquals(normalizedExpected, normalizeToString.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(normalizedExpected, normalizeToString.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(normalizedExpected, normalizeToString.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(normalizedExpected, normalizeToString.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    }
