    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray={" + BR
                   + "    1.0," + BR
                   + "    2.0" + BR
                   + "  }," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";

        final Function<String, Map<String, String>> parseFields = s -> {
            final String[] lines = s.split("\\R");
            final Map<String, String> fields = new TreeMap<>();
            fields.put("@prefix", lines[0]);
            fields.put("@suffix", lines[lines.length - 1]);

            int i = 1;
            while (i < lines.length - 1) {
                final String line = lines[i];
                if (!line.startsWith("  ") || line.indexOf('=') <= 0) {
                    i++;
                    continue;
                }

                final int eq = line.indexOf('=');
                final String name = line.substring(2, eq);
                final StringBuilder value = new StringBuilder(line.substring(eq + 1));
                i++;

                while (i < lines.length - 1
                        && !(lines[i].startsWith("  ") && lines[i].indexOf('=') > 0)) {
                    value.append(BR).append(lines[i]);
                    i++;
                }

                String v = value.toString();
                if (v.endsWith(",")) {
                    v = v.substring(0, v.length() - 1);
                }
                fields.put(name, v);
            }

            return fields;
        };

        assertEquals(parseFields.apply(exp), parseFields.apply(toString(wa)));
    }
