                + "<if test=\"id != null\"> AND id = #{id}</if>"
                + "<if test=\"state != null\"> AND state = #{state}</if>"
                + "<if test=\"userName != null\"> AND user_name = #{userName}</if></where>";

        Pattern sqlPattern = Pattern.compile("SELECT\\s+(.*?)\\s+FROM\\s+(.*?)<where>(.*)</where>", Pattern.DOTALL);
        Matcher sqlMatcher = sqlPattern.matcher(sql);
        Assert.assertTrue("SQL should match SELECT-FROM-WHERE structure", sqlMatcher.matches());
        String actualColumns = sqlMatcher.group(1).trim();
        String actualTable = sqlMatcher.group(2).trim();
        String actualWhere = sqlMatcher.group(3).trim();

        String[] columnArray = actualColumns.split(",");
        List<String> columnList = new ArrayList<String>();
        for (String column : columnArray) {
            columnList.add(column.trim());
        }
        Collections.sort(columnList);
        StringBuilder sortedColumnsBuilder = new StringBuilder();
        for (int i = 0; i < columnList.size(); i++) {
            if (i > 0) {
                sortedColumnsBuilder.append(",");
            }
            sortedColumnsBuilder.append(columnList.get(i));
        }
        String sortedColumns = sortedColumnsBuilder.toString();

        Pattern ifPattern = Pattern.compile("<if test=\"(.*?)\">(.*?)</if>", Pattern.DOTALL);
        Matcher ifMatcher = ifPattern.matcher(actualWhere);
        List<String> ifBlocks = new ArrayList<String>();
        while (ifMatcher.find()) {
            ifBlocks.add(ifMatcher.group(0));
        }
        Collections.sort(ifBlocks);
        StringBuilder sortedWhereBuilder = new StringBuilder();
        for (String ifBlock : ifBlocks) {
            sortedWhereBuilder.append(ifBlock);
        }
        String sortedWhere = sortedWhereBuilder.toString();

        String actualCanonicalSql = "SELECT " + sortedColumns + "  FROM " + actualTable + " <where>" + sortedWhere + "</where>";
        Assert.assertEquals(expectedSql, actualCanonicalSql);

