    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray={" + BR
                   + "    1.0," + BR
                   + "    2.0" + BR
                   + "  }," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";

        final Function<String, String> canonicalize = s -> {
            final String[] lines = s.split("\\R");
            final String prefix = lines[0];
            final String suffix = lines[lines.length - 1];

            final List<String> fields = new ArrayList<>();
            int i = 1;
            while (i < lines.length - 1) {
                final List<String> fieldLines = new ArrayList<>();
                fieldLines.add(lines[i]);
                i++;
                while (i < lines.length - 1
                        && !(lines[i].startsWith("  ") && lines[i].indexOf('=') > 0)) {
                    fieldLines.add(lines[i]);
                    i++;
                }
                fields.add(String.join("\n", fieldLines));
            }

            fields.sort(String::compareTo);
            return prefix + "\n" + String.join("\n", fields) + "\n" + suffix;
        };

        assertEquals(canonicalize.apply(exp), canonicalize.apply(toString(wa)));
    }
