    @Test
    public void testReflectionStatics() {
        final ReflectionStaticFieldsFixture instance1 = new ReflectionStaticFieldsFixture();
        final String prefix = instance1.getClass().getName() + "@" + Integer.toHexString(System.identityHashCode(instance1));
        final java.util.function.Function<String, String> normalizeToString = s -> {
            final int start = s.indexOf('[');
            final int end = s.lastIndexOf(']');
            final String fields = s.substring(start + 1, end);
            final List<String> fieldList = new ArrayList<>(java.util.Arrays.asList(fields.split(",")));
            java.util.Collections.sort(fieldList);
            return s.substring(0, start) + "[" + String.join(",", fieldList) + "]";
        };
        assertEquals(
            prefix + "[instanceInt=67890,instanceString=instanceString,staticInt=12345,staticString=staticString]",
            normalizeToString.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            prefix + "[instanceInt=67890,instanceString=instanceString,staticInt=12345,staticString=staticString,staticTransientInt=54321,staticTransientString=staticTransientString,transientInt=98765,transientString=transientString]",
            normalizeToString.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            prefix + "[instanceInt=67890,instanceString=instanceString,staticInt=12345,staticString=staticString]",
            normalizeToString.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            prefix + "[instanceInt=67890,instanceString=instanceString,staticInt=12345,staticString=staticString]",
            normalizeToString.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));
    }
