    public void testReflectionHierarchy() {
        final Function<String, String> canonical = s -> {
            final int bracket = s.indexOf('[');
            final String prefix = s.substring(0, bracket);
            final String inside = s.substring(bracket + 1, s.length() - 1);
            if (inside.isEmpty()) {
                return s;
            }
            final String[] fields = inside.split(",", -1);
            Arrays.sort(fields);
            return prefix + "[" + String.join(",", fields) + "]";
        };

        final ReflectionTestFixtureA baseA = new ReflectionTestFixtureA();
