        final String actual = toString(wa);

        final Pattern FIELD_HEADER = Pattern.compile("^  (\\w+)=(.*)$");
        final Function<String, Map<String, String>> toFieldMap = s -> {
            final String[] lines = s.split("\\R");
            final Map<String, String> fields = new LinkedHashMap<>();
            String currentField = null;
            StringBuilder currentValue = new StringBuilder();
            for (int i = 1; i < lines.length - 1; i++) {
                final String line = lines[i];
                final Matcher matcher = FIELD_HEADER.matcher(line);
                if (matcher.matches()) {
                    if (currentField != null) {
                        String value = currentValue.toString();
                        if (value.endsWith(",")) {
                            value = value.substring(0, value.length() - 1);
                        }
                        fields.put(currentField, value);
                    }
                    currentField = matcher.group(1);
                    currentValue = new StringBuilder(matcher.group(2));
                } else if (currentValue.length() > 0) {
                    currentValue.append(BR).append(line);
                }
            }
            if (currentField != null) {
                String value = currentValue.toString();
                if (value.endsWith(",")) {
                    value = value.substring(0, value.length() - 1);
                }
                fields.put(currentField, value);
            }
            return fields;
        };

        final String[] expectedLines = exp.split("\\R");
        final String[] actualLines = actual.split("\\R");
