  @Test
  public void testAvroDoc() throws Exception {
    String expected = "{\"type\":\"record\",\"name\":\"DocTest\",\"namespace\":\"org.apache.avro.reflect.TestReflect\","
        + "\"doc\":\"DocTest class docs\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"doc\":\"Some Documentation\"},"
        + "{\"name\":\"enums\",\"type\":{\"type\":\"enum\",\"name\":\"DocTestEnum\","
        + "\"symbols\":[\"ENUM_1\",\"ENUM_2\"]},\"doc\":\"Some other Documentation\"},"
        + "{\"name\":\"defaultTest\",\"type\":{\"type\":\"record\",\"name\":\"DefaultTest\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"default\":1}]},\"doc\":\"And again\"}]}";

    ObjectMapper mapper = new ObjectMapper();
    JsonNode expectedNode = mapper.readTree(expected);
    JsonNode actualNode = mapper.readTree(ReflectData.get().getSchema(DocTest.class).toString());

    class JsonRecordFieldNormalizer {
      private final ObjectMapper mapper;

      JsonRecordFieldNormalizer(ObjectMapper mapper) {
        this.mapper = mapper;
      }

      JsonNode normalize(JsonNode node) {
        if (node.isObject()) {
          ObjectNode object = (ObjectNode) node;
          List<String> fieldNames = new ArrayList<>();
          object.fieldNames().forEachRemaining(fieldNames::add);
          for (String fieldName : fieldNames) {
            object.set(fieldName, normalize(object.get(fieldName)));
          }

          if (object.has("fields") && object.get("fields").isArray()) {
            ArrayNode fields = (ArrayNode) object.get("fields");
            List<JsonNode> fieldList = new ArrayList<>();
            fields.forEach(fieldList::add);
            fieldList.sort(Comparator.comparing(field -> field.get("name").asText()));

            ArrayNode sortedFields = mapper.createArrayNode();
            for (JsonNode field : fieldList) {
              sortedFields.add(field);
            }
            object.set("fields", sortedFields);
          }
          return object;
        } else if (node.isArray()) {
          ArrayNode array = (ArrayNode) node;
          for (int i = 0; i < array.size(); i++) {
            array.set(i, normalize(array.get(i)));
          }
          return array;
        } else {
          return node;
        }
      }
    }

    JsonRecordFieldNormalizer normalizer = new JsonRecordFieldNormalizer(mapper);
    JsonNode normalizedExpected = normalizer.normalize(expectedNode);
    JsonNode normalizedActual = normalizer.normalize(actualNode);

    assertEquals(normalizedExpected, normalizedActual);
  }
