  @Test public void xmlRequestBody() throws Exception {
    server.enqueue(new MockResponse());

    Call<Void> call = service.postXml(SAMPLE_CONTACT);
    call.execute();

    RecordedRequest request = server.takeRequest();
    assertThat(request.getHeader("Content-Type")).isEqualTo("application/xml; charset=utf-8");

    String actualXml = request.getBody().readUtf8();
    DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
    dbf.setNamespaceAware(false);
    dbf.setIgnoringElementContentWhitespace(true);
    DocumentBuilder db = dbf.newDocumentBuilder();

    class XmlNormalizer {
      String normalize(String xml) throws Exception {
        Document doc = db.parse(new InputSource(new StringReader(xml)));
        return normalizeElement(doc.getDocumentElement());
      }

      String normalizeElement(Element element) {
        StringBuilder builder = new StringBuilder();
        builder.append('<').append(element.getTagName());

        NamedNodeMap attributes = element.getAttributes();
        Map<String, String> sortedAttributes = new TreeMap<String, String>();
        for (int i = 0; i < attributes.getLength(); i++) {
          Node attribute = attributes.item(i);
          sortedAttributes.put(attribute.getNodeName(), attribute.getNodeValue());
        }
        for (Map.Entry<String, String> attribute : sortedAttributes.entrySet()) {
          builder.append(' ')
              .append(attribute.getKey())
              .append("=\"")
              .append(attribute.getValue())
              .append('"');
        }
        builder.append('>');

        List<String> children = new ArrayList<String>();
        NodeList childNodes = element.getChildNodes();
        for (int i = 0; i < childNodes.getLength(); i++) {
          Node child = childNodes.item(i);
          if (child.getNodeType() == Node.ELEMENT_NODE) {
            children.add(normalizeElement((Element) child));
          } else if (child.getNodeType() == Node.TEXT_NODE
              || child.getNodeType() == Node.CDATA_SECTION_NODE) {
            String text = child.getNodeValue();
            if (text != null && !text.trim().isEmpty()) {
              children.add("#text:" + text.trim());
            }
          }
        }
        Collections.sort(children);
        for (String child : children) {
          builder.append(child);
        }

        builder.append("</").append(element.getTagName()).append('>');
        return builder.toString();
      }
    }

    XmlNormalizer normalizer = new XmlNormalizer();
    assertThat(normalizer.normalize(actualXml)).isEqualTo(normalizer.normalize(SAMPLE_CONTACT_XML));
  }
