  @Test public void userSuppliedJaxbContext() throws Exception {
    JAXBContext context = JAXBContext.newInstance(Contact.class);
    JaxbConverterFactory factory = JaxbConverterFactory.create(context);
    Retrofit retrofit = new Retrofit.Builder()
        .baseUrl(server.url("/"))
        .addConverterFactory(factory)
        .build();
    service = retrofit.create(Service.class);

    server.enqueue(new MockResponse());

    Call<Void> call = service.postXml(SAMPLE_CONTACT);
    call.execute();

    RecordedRequest request = server.takeRequest();
    assertThat(request.getHeader("Content-Type")).isEqualTo("application/xml; charset=utf-8");

    class XmlCanonicalizer {
      String canonicalize(String xml) throws Exception {
        String declaration = "";
        if (xml.startsWith("<?xml")) {
          int end = xml.indexOf("?>");
          if (end != -1) {
            declaration = xml.substring(0, end + 2);
          }
        }

        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        dbf.setNamespaceAware(false);
        dbf.setIgnoringComments(true);
        Document doc = dbf.newDocumentBuilder().parse(
            new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)));
        return declaration + canonicalizeNode(doc.getDocumentElement());
      }

      String canonicalizeNode(Node node) {
        if (node.getNodeType() == Node.TEXT_NODE) {
          String text = node.getNodeValue().trim();
          return text.isEmpty() ? "" : "#text:" + text;
        }
        if (node.getNodeType() != Node.ELEMENT_NODE) {
          return "";
        }

        Element element = (Element) node;
        StringBuilder sb = new StringBuilder();
        sb.append("<").append(element.getTagName());

        List<String> attrs = new ArrayList<>();
        NamedNodeMap attributeMap = element.getAttributes();
        for (int i = 0; i < attributeMap.getLength(); i++) {
          Node attr = attributeMap.item(i);
          attrs.add(attr.getNodeName() + "=\"" + attr.getNodeValue() + "\"");
        }
        Collections.sort(attrs);
        for (String attr : attrs) {
          sb.append(" ").append(attr);
        }
        sb.append(">");

        List<String> children = new ArrayList<>();
        NodeList childNodes = element.getChildNodes();
        for (int i = 0; i < childNodes.getLength(); i++) {
          String child = canonicalizeNode(childNodes.item(i));
          if (!child.isEmpty()) {
            children.add(child);
          }
        }
        Collections.sort(children);
        for (String child : children) {
          sb.append(child);
        }

        return sb.append("</").append(element.getTagName()).append(">").toString();
      }
    }

    XmlCanonicalizer canonicalizer = new XmlCanonicalizer();
    assertThat(canonicalizer.canonicalize(request.getBody().readUtf8()))
        .isEqualTo(canonicalizer.canonicalize(SAMPLE_CONTACT_XML));
  }
