//<fix start>
    @Test
    public void testReflectionHashCodeExcludeFields() {
        // Use values whose pairwise differences are multiples of 2^30 so that
        // reflection field order cannot affect the resulting int hash code.
        final int oneValue = 0;
        final int twoValue = 1 << 30;
        final int threeValue = 2 << 30;
        final TestObjectWithMultipleFields x = new TestObjectWithMultipleFields(oneValue, twoValue, threeValue);

        assertEquals(((17 * 37 + oneValue) * 37 + twoValue) * 37 + threeValue, HashCodeBuilder.reflectionHashCode(x));

        assertEquals(((17 * 37 + oneValue) * 37 + twoValue) * 37 + threeValue, HashCodeBuilder.reflectionHashCode(x, (String[]) null));
        assertEquals(((17 * 37 + oneValue) * 37 + twoValue) * 37 + threeValue, HashCodeBuilder.reflectionHashCode(x));
        assertEquals(((17 * 37 + oneValue) * 37 + twoValue) * 37 + threeValue, HashCodeBuilder.reflectionHashCode(x, "xxx"));

        assertEquals((17 * 37 + oneValue) * 37 + threeValue, HashCodeBuilder.reflectionHashCode(x, "two"));
        assertEquals((17 * 37 + oneValue) * 37 + twoValue, HashCodeBuilder.reflectionHashCode(x, "three"));

        assertEquals(17 * 37 + oneValue, HashCodeBuilder.reflectionHashCode(x, "two", "three"));

        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three"));
        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three", "xxx"));
    }
