//<fix start>
    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray={" + BR
                   + "    1.0," + BR
                   + "    2.0" + BR
                   + "  }," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";

        final java.util.function.Function<String, Map<String, String>> parse = s -> {
            final String[] lines = s.split("\\R");
            final Map<String, String> map = new LinkedHashMap<>();
            map.put("__prefix__", lines[0]);
            map.put("__suffix__", lines[lines.length - 1]);
            int i = 1;
            while (i < lines.length - 1) {
                final String line = lines[i];
                if (line.startsWith("  ")) {
                    final int eq = line.indexOf('=');
                    final String key = line.substring(2, eq);
                    final String value = line.substring(eq + 1);
                    if ("{".equals(value)) {
                        final StringBuilder nested = new StringBuilder("{");
                        i++;
                        while (i < lines.length - 1 && !(lines[i].equals("  }") || lines[i].equals("  },"))) {
                            nested.append(lines[i]).append(BR);
                            i++;
                        }
                        nested.append('}');
                        map.put(key, nested.toString());
                    } else {
                        map.put(key, value.endsWith(",") ? value.substring(0, value.length() - 1) : value);
                    }
                }
                i++;
            }
            return map;
        };

        assertEquals(parse.apply(exp), parse.apply(toString(wa)));
    }
