//<fix start>
    @Test
    public void testEquals2Annotations()
    {
        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

        Assert.assertEquals(a.getBeanClass(), b.getBeanClass());
        Assert.assertEquals(a.getPath(), b.getPath());
        Assert.assertEquals(a.isDelegate(), b.isDelegate());

        Object aQualifiersObj = a.getQualifiers();
        Object bQualifiersObj = b.getQualifiers();
        Assert.assertNotNull(aQualifiersObj);
        Assert.assertNotNull(bQualifiersObj);

        List<Annotation> aQualifiers = new ArrayList<>();
        if (aQualifiersObj instanceof Annotation[])
        {
            for (Annotation annotation : (Annotation[]) aQualifiersObj)
            {
                aQualifiers.add(annotation);
            }
        }
        else if (aQualifiersObj instanceof Iterable)
        {
            for (Object annotation : (Iterable<?>) aQualifiersObj)
            {
                aQualifiers.add((Annotation) annotation);
            }
        }
        else
        {
            Assert.fail("Unexpected qualifiers type: " + aQualifiersObj.getClass().getName());
        }

        List<Annotation> bQualifiers = new ArrayList<>();
        if (bQualifiersObj instanceof Annotation[])
        {
            for (Annotation annotation : (Annotation[]) bQualifiersObj)
            {
                bQualifiers.add(annotation);
            }
        }
        else if (bQualifiersObj instanceof Iterable)
        {
            for (Object annotation : (Iterable<?>) bQualifiersObj)
            {
                bQualifiers.add((Annotation) annotation);
            }
        }
        else
        {
            Assert.fail("Unexpected qualifiers type: " + bQualifiersObj.getClass().getName());
        }

        Assert.assertEquals(aQualifiers.size(), bQualifiers.size());

        Comparator<Annotation> qualifierComparator = new Comparator<Annotation>()
        {
            @Override
            public int compare(Annotation left, Annotation right)
            {
                int typeComparison = left.annotationType().getName().compareTo(right.annotationType().getName());
                if (typeComparison != 0)
                {
                    return typeComparison;
                }

                if (left instanceof AnnotationWithBindingMember && right instanceof AnnotationWithBindingMember)
                {
                    AnnotationWithBindingMember leftBinding = (AnnotationWithBindingMember) left;
                    AnnotationWithBindingMember rightBinding = (AnnotationWithBindingMember) right;

                    int valueComparison = leftBinding.value().compareTo(rightBinding.value());
                    if (valueComparison != 0)
                    {
                        return valueComparison;
                    }

                    return Integer.compare(leftBinding.number(), rightBinding.number());
                }

                return left.toString().compareTo(right.toString());
            }
        };

        Collections.sort(aQualifiers, qualifierComparator);
