        Assert.assertFalse("serialized JSON should not be empty", text1.isEmpty());

        JSONObject actual = JSON.parseObject(text1, Feature.DisableSpecialKeyDetect);
        Assert.assertNotNull("parsed serialized JSON should not be null", actual);
        Assert.assertEquals("serialized JSON outer map should contain exactly two entries", 2, actual.size());
        Assert.assertTrue("serialized JSON outer map should contain key 1001", actual.containsKey("1001"));
        Assert.assertEquals("outer @type should be java.util.LinkedHashMap", "java.util.LinkedHashMap", actual.getString(JSON.DEFAULT_TYPE_KEY));

        Object actualValue = actual.get("1001");
        Assert.assertTrue("value for key 1001 should be a JSONObject", actualValue instanceof JSONObject);
        JSONObject actualItem = (JSONObject) actualValue;
        Assert.assertEquals("nested JSON should contain exactly two entries", 2, actualItem.size());
        Assert.assertEquals("nested id should be 1001", Integer.valueOf(1001), actualItem.getInteger("id"));
        Assert.assertEquals("nested @type should be DianDianCart", "com.alibaba.json.bvt.writeClassName.WriteDuplicateType$DianDianCart", actualItem.getString(JSON.DEFAULT_TYPE_KEY));

        JSONObject expected = JSON.parseObject("{\"@type\":\"java.util.LinkedHashMap\",\"1001\":{\"@type\":\"com.alibaba.json.bvt.writeClassName.WriteDuplicateType$DianDianCart\",\"id\":1001}}", Feature.DisableSpecialKeyDetect);
