  public void testMultipleFieldAliases() {
    Schema intType = Schema.create(org.apache.avro.Schema.Type.INT);
    assertNotNull("Schema.create(INT) must not return null", intType);
    assertEquals("Schema.create(INT) must produce an int schema",
        org.apache.avro.Schema.Type.INT, intType.getType());

    Schema expectedSchema = SchemaBuilder.record(ClassWithMultipleAliasesOnField.class.getSimpleName())
        .namespace("org.apache.avro.reflect.TestReflect").fields().name("primitiveField").aliases("alias1", "alias2")
        .type(intType).noDefault().endRecord();

    Schema actualSchema = ReflectData.get().getSchema(ClassWithMultipleAliasesOnField.class);
    Field actualField = actualSchema.getField("primitiveField");
    assertNotNull("primitiveField must be present in the reflected schema", actualField);

    assertEquals("The primitiveField type must be int", intType, actualField.schema());
    assertFalse("primitiveField must have no default value", actualField.hasDefaultValue());

    List<String> expectedAliases = new ArrayList<>(Arrays.asList("alias1", "alias2"));
    List<String> actualAliases = new ArrayList<>(actualField.aliases());
    Collections.sort(expectedAliases);
    Collections.sort(actualAliases);
    assertEquals("All aliases must be present exactly once", expectedAliases, actualAliases);

    assertEquals("Expected and actual schemas must be structurally equal", expectedSchema, actualSchema);
  }
