@Test
public void testReflectionStatics() {
    final ReflectionStaticFieldsFixture instance1 = new ReflectionStaticFieldsFixture();
    final String expectedBase = this.toBaseString(instance1);

    final java.util.function.UnaryOperator<String> normalize = s -> {
        final int start = s.indexOf('[');
        final int end = s.lastIndexOf(']');
        final String content = s.substring(start + 1, end);
        final String[] fields = content.split(",", -1);
        java.util.Arrays.sort(fields);
        return s.substring(0, start) + "[" + String.join(",", fields) + "]";
    };

    final String expectedInstance = expectedBase
            + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]";
    final String expectedAll = expectedBase
            + "[staticString=staticString,staticInt=12345,staticTransientString=staticTransientString,staticTransientInt=54321,instanceString=instanceString,instanceInt=67890,transientString=transientString,transientInt=98765]";

    assertEquals(
            normalize.apply(expectedInstance),
            normalize.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, ReflectionStaticFieldsFixture.class)));
    assertEquals(
            normalize.apply(expectedAll),
            normalize.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, ReflectionStaticFieldsFixture.class)));
    assertEquals(
            normalize.apply(expectedInstance),
            normalize.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));
    assertEquals(
            normalize.apply(expectedInstance),
            normalize.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));
}
