//<fix start>
    @Test
    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();

        final java.util.function.Function<String, java.util.Map<String, String>> toFieldMap = s -> {
            final int start = s.indexOf('[');
            final int end = s.lastIndexOf(']');
            if (start < 0 || end <= start) {
                throw new AssertionError("Missing reflection field brackets: " + s);
            }
            final java.util.Map<String, String> fields = new java.util.HashMap<>();
            final String body = s.substring(start + 1, end);
            if (!body.isEmpty()) {
                for (final String entry : body.split(",")) {
                    final int eq = entry.indexOf('=');
                    if (eq < 0) {
                        throw new AssertionError("Malformed reflection field entry: " + entry + " in " + s);
                    }
                    fields.put(entry.substring(0, eq), entry.substring(eq + 1));
                }
            }
            return fields;
        };

        final java.util.function.BiConsumer<String, String> assertReflectionStringEquals = (expected, actual) -> {
            final int expectedStart = expected.indexOf('[');
            final int actualStart = actual.indexOf('[');
            if (expectedStart < 0 || actualStart < 0) {
                throw new AssertionError("Missing reflection field brackets");
            }
            assertEquals(expected.substring(0, expectedStart), actual.substring(0, actualStart));
            assertEquals(toFieldMap.apply(expected), toFieldMap.apply(actual));
        };

        assertReflectionStringEquals.accept(
            this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890]",
            ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class));
        assertReflectionStringEquals.accept(
            this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]",
            ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class));
        assertReflectionStringEquals.accept(
            this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]",
            this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class));
        assertReflectionStringEquals.accept(
            this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]",
            this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class));
    }
