    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        String expectedWhereAllIfColumns = "<where><if test=\"id != null\"> AND id = #{id}</if><if test=\"username != null\"> AND username = #{username}</if> AND is_valid = 1</where>";

        Assert.assertTrue("where prefix missing", whereAllIfColumns.startsWith("<where>"));
        Assert.assertTrue("where suffix missing", whereAllIfColumns.endsWith("</where>"));

        String expectedWhereAllInner = expectedWhereAllIfColumns.substring("<where>".length(), expectedWhereAllIfColumns.length() - "</where>".length());
        String actualWhereAllInner = whereAllIfColumns.substring("<where>".length(), whereAllIfColumns.length() - "</where>".length());

        Pattern ifPattern = Pattern.compile("<if\\b[^>]*>.*?</if>");
        Matcher expectedIfMatcher = ifPattern.matcher(expectedWhereAllInner);
        List<String> expectedIfBlocks = new ArrayList<String>();
        int expectedLastEnd = 0;
        while (expectedIfMatcher.find()) {
            expectedIfBlocks.add(expectedIfMatcher.group());
            expectedLastEnd = expectedIfMatcher.end();
        }
        String expectedWhereAllTrailing = expectedWhereAllInner.substring(expectedLastEnd);
        Collections.sort(expectedIfBlocks);

        Matcher actualIfMatcher = ifPattern.matcher(actualWhereAllInner);
        List<String> actualIfBlocks = new ArrayList<String>();
        int actualLastEnd = 0;
        while (actualIfMatcher.find()) {
            actualIfBlocks.add(actualIfMatcher.group());
            actualLastEnd = actualIfMatcher.end();
        }
        String actualWhereAllTrailing = actualWhereAllInner.substring(actualLastEnd);

        StringBuilder actualWhereAllConcatenated = new StringBuilder();
        for (String block : actualIfBlocks) {
            actualWhereAllConcatenated.append(block);
        }
        actualWhereAllConcatenated.append(actualWhereAllTrailing);
        Assert.assertEquals("Unexpected non-if content in whereAllIfColumns", actualWhereAllInner, actualWhereAllConcatenated.toString());

        Collections.sort(actualIfBlocks);

        StringBuilder normalizedExpectedWhereAll = new StringBuilder("<where>");
        for (String block : expectedIfBlocks) {
            normalizedExpectedWhereAll.append(block);
        }
        normalizedExpectedWhereAll.append(expectedWhereAllTrailing).append("</where>");

        StringBuilder normalizedActualWhereAll = new StringBuilder("<where>");
        for (String block : actualIfBlocks) {
            normalizedActualWhereAll.append(block);
        }
        normalizedActualWhereAll.append(actualWhereAllTrailing).append("</where>");

        Assert.assertEquals(normalizedExpectedWhereAll.toString(), normalizedActualWhereAll.toString());

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        String expectedUpdateSetColumns = "<set>username = #{username},is_valid = 1,</set>";

        Assert.assertTrue("set prefix missing", updateSetColumns.startsWith("<set>"));
        Assert.assertTrue("set suffix missing", updateSetColumns.endsWith("</set>"));

        String expectedSetInner = expectedUpdateSetColumns.substring("<set>".length(), expectedUpdateSetColumns.length() - "</set>".length());
        String actualSetInner = updateSetColumns.substring("<set>".length(), updateSetColumns.length() - "</set>".length());

        Assert.assertTrue("expected set inner must end with ','", expectedSetInner.endsWith(","));
        Assert.assertTrue("actual set inner must end with ','", actualSetInner.endsWith(","));

        String expectedSetBody = expectedSetInner.substring(0, expectedSetInner.length() - 1);
        String actualSetBody = actualSetInner.substring(0, actualSetInner.length() - 1);

        List<String> expectedSetTokens = new ArrayList<String>(Arrays.asList(expectedSetBody.split(",", -1)));
        List<String> actualSetTokens = new ArrayList<String>(Arrays.asList(actualSetBody.split(",", -1)));

        Collections.sort(expectedSetTokens);
        Collections.sort(actualSetTokens);

        Assert.assertEquals("updateSetColumns assignments differ", expectedSetTokens, actualSetTokens);
    }
