    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        String expectedWhereAllIfColumns = "<where><if test=\"id != null\"> AND id = #{id}</if><if test=\"username != null\"> AND username = #{username}</if> AND is_valid = 1</where>";

        Assert.assertEquals("<where>", whereAllIfColumns.substring(0, "<where>".length()));
        Assert.assertEquals("</where>", whereAllIfColumns.substring(whereAllIfColumns.length() - "</where>".length()));

        String actualWhereAllInner = whereAllIfColumns.substring("<where>".length(), whereAllIfColumns.length() - "</where>".length());
        Pattern ifPattern = Pattern.compile("<if\\b[^>]*>.*?</if>");

        Matcher actualIfMatcher = ifPattern.matcher(actualWhereAllInner);
        List<String> actualIfBlocks = new ArrayList<String>();
        int actualIfEnd = 0;
        while (actualIfMatcher.find()) {
            actualIfBlocks.add(actualIfMatcher.group());
            actualIfEnd = actualIfMatcher.end();
        }
        String actualWhereAllTrailing = actualWhereAllInner.substring(actualIfEnd);

        StringBuilder actualWhereAllReconstructed = new StringBuilder("<where>");
        for (String actualIfBlock : actualIfBlocks) {
            actualWhereAllReconstructed.append(actualIfBlock);
        }
        actualWhereAllReconstructed.append(actualWhereAllTrailing).append("</where>");
        Assert.assertEquals("Unexpected content in whereAllIfColumns", whereAllIfColumns, actualWhereAllReconstructed.toString());

        String expectedWhereAllInner = expectedWhereAllIfColumns.substring("<where>".length(), expectedWhereAllIfColumns.length() - "</where>".length());
        Matcher expectedIfMatcher = ifPattern.matcher(expectedWhereAllInner);
        List<String> expectedIfBlocks = new ArrayList<String>();
        int expectedIfEnd = 0;
        while (expectedIfMatcher.find()) {
            expectedIfBlocks.add(expectedIfMatcher.group());
            expectedIfEnd = expectedIfMatcher.end();
        }
        String expectedWhereAllTrailing = expectedWhereAllInner.substring(expectedIfEnd);

        Collections.sort(expectedIfBlocks);
        Collections.sort(actualIfBlocks);

        Assert.assertEquals("whereAllIfColumns if blocks differ", expectedIfBlocks, actualIfBlocks);
        Assert.assertEquals("whereAllIfColumns trailing content differs", expectedWhereAllTrailing, actualWhereAllTrailing);

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        String expectedUpdateSetColumns = "<set>username = #{username},is_valid = 1,</set>";

        Assert.assertEquals("<set>", updateSetColumns.substring(0, "<set>".length()));
        Assert.assertEquals("</set>", updateSetColumns.substring(updateSetColumns.length() - "</set>".length()));

        String expectedUpdateSetInner = expectedUpdateSetColumns.substring("<set>".length(), expectedUpdateSetColumns.length() - "</set>".length());
        String actualUpdateSetInner = updateSetColumns.substring("<set>".length(), updateSetColumns.length() - "</set>".length());

        List<String> expectedUpdateSetParts = new ArrayList<String>(Arrays.asList(expectedUpdateSetInner.split(",", -1)));
        List<String> actualUpdateSetParts = new ArrayList<String>(Arrays.asList(actualUpdateSetInner.split(",", -1)));

        Collections.sort(expectedUpdateSetParts);
        Collections.sort(actualUpdateSetParts);

        Assert.assertEquals("updateSetColumns assignments differ", expectedUpdateSetParts, actualUpdateSetParts);
    }
