    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        String prefix = whereAllIfColumns.substring(0, whereAllIfColumns.indexOf("<if test="));
        String suffix = whereAllIfColumns.substring(whereAllIfColumns.lastIndexOf("</if>") + "</if>".length());

        List<String> actualIfBlocks = new ArrayList<String>();
        int start = whereAllIfColumns.indexOf("<if test=");
        while (start != -1) {
            int end = whereAllIfColumns.indexOf("</if>", start);
            Assert.assertTrue("Malformed whereAllIfColumns: " + whereAllIfColumns, end != -1);
            actualIfBlocks.add(whereAllIfColumns.substring(start, end + "</if>".length()));
            start = whereAllIfColumns.indexOf("<if test=", end);
        }

        List<String> expectedIfBlocks = new ArrayList<String>();
        expectedIfBlocks.add("<if test=\"id != null\"> AND id = #{id}</if>");
        expectedIfBlocks.add("<if test=\"username != null\"> AND username = #{username}</if>");

        Collections.sort(actualIfBlocks);
        Collections.sort(expectedIfBlocks);

        Assert.assertEquals("<where>", prefix);
        Assert.assertEquals(" AND is_valid = 1</where>", suffix);
        Assert.assertEquals(expectedIfBlocks, actualIfBlocks);

        int blockLength = 0;
        for (String block : actualIfBlocks) {
            blockLength += block.length();
        }
        Assert.assertEquals(whereAllIfColumns.length(), prefix.length() + suffix.length() + blockLength);

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        Assert.assertEquals("<set>username = #{username},is_valid = 1,</set>", updateSetColumns);
    }
