    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        String wherePKPrefix = "<where>";
        String wherePKSuffix = "</where>";
        Assert.assertTrue(wherePKColumns.startsWith(wherePKPrefix));
        Assert.assertTrue(wherePKColumns.endsWith(wherePKSuffix));
        String wherePKContent = wherePKColumns.substring(wherePKPrefix.length(), wherePKColumns.length() - wherePKSuffix.length());
        Assert.assertTrue(wherePKContent.startsWith(" AND "));
        String normalizedPKContent = wherePKContent.substring(" AND ".length());
        List<String> actualPKConditions = new ArrayList<String>(Arrays.asList(normalizedPKContent.split(" AND ", -1)));
        List<String> expectedPKConditions = new ArrayList<String>(Arrays.asList("id = #{id}", "is_valid = 1"));
        Collections.sort(actualPKConditions);
        Collections.sort(expectedPKConditions);
        Assert.assertEquals(expectedPKConditions, actualPKConditions);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        String whereAllIfPrefix = "<where>";
        String whereAllIfSuffix = " AND is_valid = 1</where>";
        Assert.assertTrue(whereAllIfColumns.startsWith(whereAllIfPrefix));
        Assert.assertTrue(whereAllIfColumns.endsWith(whereAllIfSuffix));
        String whereAllIfContent = whereAllIfColumns.substring(whereAllIfPrefix.length(), whereAllIfColumns.length() - whereAllIfSuffix.length());

        List<String> actualIfBlocks = new ArrayList<String>();
        int fromIndex = 0;
        while (true) {
            int start = whereAllIfContent.indexOf("<if test=", fromIndex);
            if (start == -1) {
                break;
            }
            int end = whereAllIfContent.indexOf("</if>", start);
            Assert.assertTrue("Malformed whereAllIfColumns: " + whereAllIfColumns, end != -1);
            actualIfBlocks.add(whereAllIfContent.substring(start, end + "</if>".length()));
            fromIndex = end + "</if>".length();
        }

        StringBuilder reassembledWhereAllIf = new StringBuilder(whereAllIfPrefix);
        for (String block : actualIfBlocks) {
            reassembledWhereAllIf.append(block);
        }
        reassembledWhereAllIf.append(whereAllIfSuffix);
        Assert.assertEquals(whereAllIfColumns, reassembledWhereAllIf.toString());

        List<String> expectedIfBlocks = new ArrayList<String>(Arrays.asList(
                "<if test=\"id != null\"> AND id = #{id}</if>",
                "<if test=\"username != null\"> AND username = #{username}</if>"
        ));
        Collections.sort(actualIfBlocks);
        Collections.sort(expectedIfBlocks);
        Assert.assertEquals(expectedIfBlocks, actualIfBlocks);

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        String updateSetPrefix = "<set>";
        String updateSetSuffix = "</set>";
        Assert.assertTrue(updateSetColumns.startsWith(updateSetPrefix));
        Assert.assertTrue(updateSetColumns.endsWith(updateSetSuffix));
        String updateSetContent = updateSetColumns.substring(updateSetPrefix.length(), updateSetColumns.length() - updateSetSuffix.length());

        List<String> actualUpdateSetParts = new ArrayList<String>(Arrays.asList(updateSetContent.split(",", -1)));
        List<String> expectedUpdateSetParts = new ArrayList<String>(Arrays.asList("username = #{username}", "is_valid = 1", ""));
        Collections.sort(actualUpdateSetParts);
        Collections.sort(expectedUpdateSetParts);
        Assert.assertEquals(expectedUpdateSetParts, actualUpdateSetParts);
    }
