    @Test
    public void noArray() {
        final WithArrays wa = new WithArrays();
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray=<null>," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";
        final String actual = toString(wa);

        final String[] expectedLines = exp.split(BR, -1);
        final String[] actualLines = actual.split(BR, -1);

        assertEquals(expectedLines[0], actualLines[0]);
        assertEquals(expectedLines[expectedLines.length - 1], actualLines[actualLines.length - 1]);

        final List<String> expectedFields = new ArrayList<>();
        for (int i = 1; i < expectedLines.length - 1; i++) {
            String line = expectedLines[i].trim();
            if (line.endsWith(",")) {
                line = line.substring(0, line.length() - 1);
            }
            expectedFields.add(line);
        }

        final List<String> actualFields = new ArrayList<>();
        for (int i = 1; i < actualLines.length - 1; i++) {
            String line = actualLines[i].trim();
            if (line.endsWith(",")) {
                line = line.substring(0, line.length() - 1);
            }
            actualFields.add(line);
        }

        expectedFields.sort((a, b) -> a.compareTo(b));
        actualFields.sort((a, b) -> a.compareTo(b));

        assertEquals(expectedFields, actualFields);
    }
