    @Test
    public void testEquals2Annotations() throws Exception
    {
        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

        Field qualifiersField = BeanCacheKey.class.getDeclaredField("qualifiers");
        qualifiersField.setAccessible(true);

        Set<Annotation> qualsA = new HashSet<>();
        Set<Annotation> qualsB = new HashSet<>();

        Object qualsObjA = qualifiersField.get(a);
        Object qualsObjB = qualifiersField.get(b);

        if (qualsObjA instanceof Collection)
        {
            for (Object obj : (Collection<?>) qualsObjA)
            {
                qualsA.add((Annotation) obj);
            }
        }
        else if (qualsObjA instanceof Annotation[])
        {
            for (Annotation ann : (Annotation[]) qualsObjA)
            {
                qualsA.add(ann);
            }
        }
        else
        {
            Assert.fail("Unexpected qualifiers field type: " + qualsObjA.getClass().getName());
        }

        if (qualsObjB instanceof Collection)
        {
            for (Object obj : (Collection<?>) qualsObjB)
            {
                qualsB.add((Annotation) obj);
            }
        }
        else if (qualsObjB instanceof Annotation[])
        {
            for (Annotation ann : (Annotation[]) qualsObjB)
            {
                qualsB.add(ann);
            }
        }
        else
        {
            Assert.fail("Unexpected qualifiers field type: " + qualsObjB.getClass().getName());
        }

        Assert.assertEquals("Qualifiers should be equal as sets", qualsA, qualsB);
        Assert.assertEquals("Hash codes should match", a.hashCode(), b.hashCode());
    }
