    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String str = toString(wa);
        final String prefix = getClassPrefix(wa) + "[" + BR;

        assertTrue(str.startsWith(prefix), "Unexpected start: " + str);
        assertTrue(str.endsWith(BR + "]"), "Unexpected end: " + str);

        final List<String> lines = new ArrayList<>();
        for (final String line : str.split("\\R")) {
            String trimmed = line.trim();
            if (trimmed.endsWith(",")) {
                trimmed = trimmed.substring(0, trimmed.length() - 1);
            }
            lines.add(trimmed);
        }

        assertTrue(lines.contains("boolArray=<null>"), "boolArray missing or malformed: " + str);
        assertTrue(lines.contains("charArray=<null>"), "charArray missing or malformed: " + str);
        assertTrue(lines.contains("intArray=<null>"), "intArray missing or malformed: " + str);
        assertTrue(lines.contains("longArray=<null>"), "longArray missing or malformed: " + str);
        assertTrue(lines.contains("stringArray=<null>"), "stringArray missing or malformed: " + str);

        final int open = lines.indexOf("doubleArray={");
        final int first = lines.indexOf("1.0");
        final int second = lines.indexOf("2.0");
        final int close = lines.indexOf("}");
        assertTrue(open >= 0, "doubleArray opening missing or malformed: " + str);
        assertTrue(first > open, "doubleArray[0] missing or misordered: " + str);
        assertTrue(second > first, "doubleArray[1] missing or misordered: " + str);
        assertTrue(close > second, "doubleArray closing missing or misordered: " + str);
    }
