        final String actual = toString(wa);

        final Function<String, List<String>> sortedFieldBlocks = s -> {
            final List<String> lines = new ArrayList<>(Arrays.asList(s.split("\\R")));
            final List<String> blocks = new ArrayList<>();
            for (int i = 1; i < lines.size() - 1; ) {
                final String line = lines.get(i);
                if (line.startsWith("  ") && !line.startsWith("   ") && line.indexOf('=') > 0) {
                    final StringBuilder block = new StringBuilder(line);
                    i++;
                    while (i < lines.size() - 1
                            && !(lines.get(i).startsWith("  ")
                                 && !lines.get(i).startsWith("   ")
                                 && lines.get(i).indexOf('=') > 0)) {
                        block.append('\n').append(lines.get(i));
                        i++;
                    }
                    blocks.add(block.toString());
                } else {
                    // Keep any stray line (for example an unexpected field separator
                    // injected after the content start), so the complete sorted
                    // representation will not match.
                    blocks.add(line);
                    i++;
                }
            }
            Collections.sort(blocks);
            return blocks;
        };

        final String[] expLines = exp.split("\\R");
        final String[] actualLines = actual.split("\\R");
        assertEquals(expLines[0], actualLines[0], "unexpected content start");
        assertEquals(expLines[expLines.length - 1], actualLines[actualLines.length - 1],
                "unexpected content end");
