    @Test
    public void test() {
        Class<?> entityClass = User.class;
        EntityHelper.initEntityNameMap(entityClass, config);
        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String sql = sqlBuilder.toString();

        // Parse the SQL components precisely, without relying on unordered column/if-block order.
        final String selectPrefix = "SELECT ";
        Assert.assertTrue("SQL must start with SELECT ", sql.startsWith(selectPrefix));
        int fromIndex = sql.indexOf(" FROM ");
        Assert.assertTrue("SQL must contain ' FROM '", fromIndex >= 0);
        int whereIndex = sql.indexOf(" <where>");
        Assert.assertTrue("SQL must contain ' <where>'", whereIndex >= 0);
        int whereEndIndex = sql.indexOf("</where>");
        Assert.assertTrue("SQL must contain '</where>'", whereEndIndex >= 0);
        Assert.assertTrue("FROM must precede WHERE", fromIndex < whereIndex);
        Assert.assertTrue("WHERE must precede </where>", whereIndex < whereEndIndex);
        Assert.assertEquals("</where> must be at the end of SQL", sql.length(), whereEndIndex + "</where>".length());

        String actualColumns = sql.substring(selectPrefix.length(), fromIndex);
        String actualTable = sql.substring(fromIndex + " FROM ".length(), whereIndex);
        String actualWhere = sql.substring(whereIndex + " <where>".length(), whereEndIndex);

        String[] columnArray = actualColumns.split(",");
        Assert.assertEquals("Should have 4 select columns", 4, columnArray.length);
        List<String> columnList = new ArrayList<String>(Arrays.asList(columnArray));
        Collections.sort(columnList);

        StringBuilder sortedColumns = new StringBuilder();
        for (int i = 0; i < columnList.size(); i++) {
            if (i > 0) {
                sortedColumns.append(",");
            }
            sortedColumns.append(columnList.get(i));
        }

        List<String> ifBlockList = new ArrayList<String>();
        int searchFrom = 0;
        while (true) {
            int ifStart = actualWhere.indexOf("<if test=\"", searchFrom);
            if (ifStart < 0) {
                break;
            }
            int ifEnd = actualWhere.indexOf("</if>", ifStart);
            Assert.assertTrue("Each if block must have a closing tag", ifEnd >= 0);
            ifBlockList.add(actualWhere.substring(ifStart, ifEnd + "</if>".length()));
            searchFrom = ifEnd + "</if>".length();
        }
        Assert.assertEquals("Should have 4 if blocks", 4, ifBlockList.size());

        StringBuilder rebuiltWhere = new StringBuilder();
        for (String ifBlock : ifBlockList) {
            rebuiltWhere.append(ifBlock);
        }
        Assert.assertEquals("WHERE must consist only of if blocks", actualWhere, rebuiltWhere.toString());

        List<String> sortedIfBlocks = new ArrayList<String>(ifBlockList);
        Collections.sort(sortedIfBlocks);
        StringBuilder sortedWhere = new StringBuilder();
        for (String ifBlock : sortedIfBlocks) {
            sortedWhere.append(ifBlock);
        }

        final String expectedSortedColumns = "address,id,state,user_name";
        final String expectedSortedWhere =
                "<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>"
                        + "<if test=\"id != null\"> AND id = #{id}</if>"
                        + "<if test=\"state != null\"> AND state = #{state}</if>"
                        + "<if test=\"userName != null\"> AND user_name = #{userName}</if>";

        Assert.assertEquals(expectedSortedColumns, sortedColumns.toString());
        Assert.assertEquals(expectedSortedWhere, sortedWhere.toString());
        Assert.assertEquals("user", actualTable);

        final String expectedCanonicalSql = "SELECT " + expectedSortedColumns + "  FROM user <where>" + expectedSortedWhere + "</where>";
        final String actualCanonicalSql = "SELECT " + sortedColumns.toString() + "  FROM " + actualTable + " <where>" + sortedWhere.toString() + "</where>";
        Assert.assertEquals(expectedCanonicalSql, actualCanonicalSql);

        final ResultMap resultMap = entityTable.getResultMap(configuration);
        final List<ResultMapping> resultMappings = new ArrayList<ResultMapping>(resultMap.getResultMappings());
        Assert.assertEquals(4, resultMappings.size());

        Collections.sort(resultMappings, new Comparator<ResultMapping>() {
            @Override
            public int compare(ResultMapping left, ResultMapping right) {
                return left.getColumn().compareTo(right.getColumn());
            }
        });

        final ResultMapping addressMapping = resultMappings.get(0);
        final ResultMapping idMapping = resultMappings.get(1);
        final ResultMapping stateMapping = resultMappings.get(2);
        final ResultMapping userNameMapping = resultMappings.get(3);

        Assert.assertEquals("address", addressMapping.getColumn());
        Assert.assertEquals("address", addressMapping.getProperty());
        Assert.assertEquals(AddressHandler.class, addressMapping.getTypeHandler().getClass());

        Assert.assertEquals("id", idMapping.getColumn());
        Assert.assertEquals("id", idMapping.getProperty());
        Assert.assertTrue(idMapping.getFlags().contains(ResultFlag.ID));

        Assert.assertEquals("state", stateMapping.getColumn());
        Assert.assertEquals("state", stateMapping.getProperty());
        Assert.assertEquals(EnumTypeHandler.class, stateMapping.getTypeHandler().getClass());

        Assert.assertEquals("user_name", userNameMapping.getColumn());
        Assert.assertEquals("userName", userNameMapping.getProperty());
    }
