        for (int i = 0; i < columnList.size(); i++) {
            if (i > 0) {
                sortedColumnsBuilder.append(",");
            }
            sortedColumnsBuilder.append(columnList.get(i));
        }
        final String actualColumnsSorted = sortedColumnsBuilder.toString();
        final String expectedColumnsSorted = "address,id,state,user_name";
        Assert.assertEquals(expectedColumnsSorted, actualColumnsSorted);

        List<String> ifBlocks = new ArrayList<String>();
        Pattern ifPattern = Pattern.compile("<if test=\".*?</if>", Pattern.DOTALL);
        Matcher ifMatcher = ifPattern.matcher(whereBody);
        int lastEnd = 0;
        while (ifMatcher.find()) {
            Assert.assertEquals("Unexpected text before if block", "", whereBody.substring(lastEnd, ifMatcher.start()));
            ifBlocks.add(ifMatcher.group());
            lastEnd = ifMatcher.end();
        }
