        Assert.assertEquals("Should have 4 if blocks", 4, ifBlocks.size());
        Collections.sort(ifBlocks);
        StringBuilder sortedWhereBuilder = new StringBuilder();
        for (String ifBlock : ifBlocks) {
            sortedWhereBuilder.append(ifBlock);
        }
        final String actualSortedWhere = sortedWhereBuilder.toString();
        final String expectedSortedWhere =
                "<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>"
                        + "<if test=\"id != null\"> AND id = #{id}</if>"
                        + "<if test=\"state != null\"> AND state = #{state}</if>"
                        + "<if test=\"userName != null\"> AND user_name = #{userName}</if>";
        Assert.assertEquals(expectedSortedWhere, actualSortedWhere);

        final String actualCanonicalSql = selectPrefix + actualColumnsSorted + fromDelimiter + tableAndWhereOpen + actualSortedWhere + whereClose;
        final String expectedCanonicalSql = selectPrefix + expectedColumnsSorted + fromDelimiter + tableAndWhereOpen + expectedSortedWhere + whereClose;
        Assert.assertEquals(expectedCanonicalSql, actualCanonicalSql);

        final ResultMap resultMap = entityTable.getResultMap(configuration);
