                "unexpected content end");

        final java.util.function.Function<String[], List<String>> extractFieldBlocks = lines -> {
            final List<String> blocks = new ArrayList<>();
            StringBuilder current = null;
            for (int i = 1; i < lines.length - 1; i++) {
                final String line = lines[i];
                if (line.startsWith("  ") && !line.startsWith("   ")
                        && line.matches("  [A-Za-z_$][A-Za-z0-9_$]*=.*")) {
                    if (current != null) {
                        blocks.add(current.toString());
                    }
                    current = new StringBuilder(line);
                } else if (current != null) {
                    current.append('\n').append(line);
                } else {
                    current = new StringBuilder("__stray__: " + line);
                }
            }
            if (current != null) {
                blocks.add(current.toString());
            }
            return blocks;
        };

        final List<String> expFieldBlocks = extractFieldBlocks.apply(expLines);
        final List<String> actualFieldBlocks = extractFieldBlocks.apply(actualLines);

        expFieldBlocks.sort((left, right) -> left.compareTo(right));
        actualFieldBlocks.sort((left, right) -> left.compareTo(right));

        assertEquals(expFieldBlocks, actualFieldBlocks, "unexpected field blocks");
    }
