        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray={" + BR
                   + "    1.0," + BR
                   + "    2.0" + BR
                   + "  }," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";

        final String actual = toString(wa);

        final UnaryOperator<String> normalize =
            value -> value.replace("\r\n", "\n").replace('\r', '\n');

        final String normalizedExp = normalize.apply(exp);
        final String normalizedActual = normalize.apply(actual);

        final String[] expLines = normalizedExp.split("\n", -1);
        final String[] actualLines = normalizedActual.split("\n", -1);

        assertEquals(expLines[0], actualLines[0], "unexpected content start");
        assertEquals(expLines[expLines.length - 1], actualLines[actualLines.length - 1],
                "unexpected content end");
        assertEquals(expLines.length, actualLines.length, "unexpected line count");

        final Function<String, Map<String, String>> parseFields = text -> {
            final String[] lines = text.split("\n", -1);
            final Map<String, String> fields = new LinkedHashMap<>();
            String currentKey = null;
            StringBuilder currentValue = null;

            for (int i = 1; i < lines.length - 1; i++) {
                final String line = lines[i];
                final boolean isFieldLine = line.startsWith("  ")
                    && !line.startsWith("   ")
                    && line.indexOf('=', 2) > 2
                    && line.substring(2, line.indexOf('=', 2)).matches("[A-Za-z_$][A-Za-z0-9_$]*");

                if (isFieldLine) {
                    if (currentKey != null) {
                        String block = currentValue.toString();
                        if (block.endsWith(",")) {
                            block = block.substring(0, block.length() - 1);
                        }
                        fields.put(currentKey, block);
                    }
                    currentKey = line.substring(2, line.indexOf('=', 2)).trim();
                    currentValue = new StringBuilder(line);
                } else if (currentKey != null) {
                    currentValue.append('\n').append(line);
                } else {
                    currentKey = "__stray__" + i;
                    currentValue = new StringBuilder(line);
                }
            }

            if (currentKey != null) {
                String block = currentValue.toString();
                if (block.endsWith(",")) {
                    block = block.substring(0, block.length() - 1);
                }
                fields.put(currentKey, block);
            }

            return fields;
        };

        final Map<String, String> expFields = parseFields.apply(normalizedExp);
        final Map<String, String> actualFields = parseFields.apply(normalizedActual);

        assertEquals(new TreeMap<>(expFields), new TreeMap<>(actualFields),
                "unexpected field blocks");
    }
