    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            DocumentBuilder db = dbf.newDocumentBuilder();
            Document doc = db.parse(new InputSource(new StringReader(whereAllIfColumns)));
            Element root = doc.getDocumentElement();
            Assert.assertEquals("where", root.getTagName());

            NodeList children = root.getChildNodes();
            List<Element> ifElements = new ArrayList<>();
            StringBuilder tailText = new StringBuilder();
            for (int i = 0; i < children.getLength(); i++) {
                Node node = children.item(i);
                if (node.getNodeType() == Node.ELEMENT_NODE) {
                    ifElements.add((Element) node);
                } else if (node.getNodeType() == Node.TEXT_NODE) {
                    tailText.append(node.getTextContent());
                } else {
                    Assert.fail("Unexpected node type in whereAllIfColumns: " + node.getNodeType());
                }
            }
            Assert.assertEquals("Unexpected tail text in whereAllIfColumns", " AND is_valid = 1", tailText.toString());

            Assert.assertEquals("Expected exactly 2 <if> elements in whereAllIfColumns", 2, ifElements.size());
            Map<String, String> expectedIfs = new HashMap<>();
            expectedIfs.put("id != null", " AND id = #{id}");
            expectedIfs.put("username != null", " AND username = #{username}");

            Set<String> seenTests = new HashSet<>();
            for (Element ifEl : ifElements) {
                String test = ifEl.getAttribute("test");
                Assert.assertTrue("Duplicate or unexpected test condition: " + test, seenTests.add(test));
                String expectedContent = expectedIfs.get(test);
                Assert.assertNotNull("Unexpected test condition: " + test, expectedContent);
                Assert.assertEquals("Unexpected content for test '" + test + "'", expectedContent, ifEl.getTextContent());
            }
            Assert.assertEquals("Expected both id and username conditions", 2, seenTests.size());
        } catch (Exception e) {
            Assert.fail("Failed to parse/validate whereAllIfColumns XML: " + e.getMessage());
        }

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        Assert.assertEquals("<set>username = #{username},is_valid = 1,</set>", updateSetColumns);
    }
